export const CAVE={entranceZ:30,backZ:-21,mountainRadius:43};
export function caveWidth(z){return 3.9+8.6*Math.exp(-(((z+2)/12)**4));}
export function caveFloor(x,z){return .35+.12*Math.sin(z*.3)+.08*Math.sin(x*.4)*Math.sin(z*.2);}
export function caveRoof(x,z){const width=caveWidth(z),height=6.6+3.3*Math.exp(-(((z+2)/14)**2));return caveFloor(x,z)+height*Math.sqrt(Math.max(0,1-(x/width)**2));}
export function constrainCavePoint(x,y,z){z=Math.max(CAVE.backZ+2,Math.min(CAVE.entranceZ-1,z));const width=caveWidth(z)-1.3;x=Math.max(-width,Math.min(width,x));const floor=caveFloor(x,z);return{x,y:Math.max(floor+1.25,Math.min(caveRoof(x,z)-.75,y)),z};}
export function caveWalkable(x,z,margin=.85){return z>-18&&z<26&&Math.abs(x)<caveWidth(z)-margin&&![[ -4,-4,1.2],[0,-4,1.2],[4,-4,1.2],[0,-8,1.6],[6,4,1.8]].some(([ox,oz,r])=>Math.hypot(x-ox,z-oz)<r);}
// Indexed arch surface, shared by navigation and high-resolution rendering.
export function shellData(rows=256,columns=128){const positions=[],indices=[];for(let row=0;row<=rows;row++){const z=CAVE.backZ+(CAVE.entranceZ-CAVE.backZ)*row/rows,w=caveWidth(z),h=6.6+3.3*Math.exp(-(((z+2)/14)**2));for(let col=0;col<=columns;col++){const a=col/columns*Math.PI,edge=Math.sin(a),noise=(Math.sin(a*17+z*.9)*.18+Math.sin(a*31-z*1.6)*.07)*edge;const x=Math.cos(a)*w;positions.push(x+noise*Math.cos(a),caveFloor(x,z)+Math.sin(a)*h+noise,z);if(row<rows&&col<columns){const i=row*(columns+1)+col;indices.push(i,i+1,i+columns+1,i+1,i+columns+2,i+columns+1);}}}return{positions,indices};}
export function mountainHeight(x,z){const r=Math.hypot(x/43,(z+6)/43);if(r>=1)return -1;const ridges=5*Math.abs(Math.sin(x*.2+z*.12))+1.2*Math.sin(x*1.7+z*.8)*Math.sin(z*1.3);const peaks=9*Math.exp(-((x+12)**2+(z+14)**2)/130)+7*Math.exp(-((x-15)**2+(z+7)**2)/90);return Math.pow(1-r*r,1.45)*(32+ridges+peaks)+4*Math.exp(-(((z-29)/7)**2)-((x/9)**4))-.8;}
export function mountainData(rings=192,segments=256){const positions=[],indices=[];for(let r=0;r<=rings;r++)for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2,rad=r/rings*43,x=Math.cos(a)*rad,z=-6+Math.sin(a)*rad;positions.push(x,mountainHeight(x,z),z);if(r<rings&&i<segments){const n=r*(segments+1)+i;for(const triangle of [[n,n+1,n+segments+1],[n+1,n+segments+2,n+segments+1]]){indices.push(...triangle);}}}const carved=[];for(let i=0;i<indices.length;i+=3){const tri=indices.slice(i,i+3);const x=tri.reduce((s,j)=>s+positions[j*3],0)/3,y=tri.reduce((s,j)=>s+positions[j*3+1],0)/3,z=tri.reduce((s,j)=>s+positions[j*3+2],0)/3;if(!(z>17&&Math.abs(x)<5.3&&y<8.2))carved.push(...tri);}return{positions,indices:carved};}
